import { query, type HookCallback, type Options } from "@anthropic-ai/claude-agent-sdk/core";
const logWorkflowRun: HookCallback = async (input) => {  // prints the runId, the handle for resumeFromRunId
  if (input.hook_event_name === "PostToolUse") console.log("Workflow:", JSON.stringify(input.tool_response));
  return {};
};
const options: Options = {
  model: "claude-opus-5-5",
  effort: "medium",
  cwd: "/work/fcp",
  settingSources: ["user", "project"],                  // "user" so saved workflows in ~/.claude/workflows/ load
  tools: { type: "preset", preset: "claude_code" },
  permissionMode: "dontAsk", allowedTools: ["Read", "Grep", "Glob", "Bash", "Workflow"],  // as in G3-19; try once without Workflow
  settings: JSON.stringify({ enableWorkflows: true, workflowSizeGuideline: "small" }),  // size is advice, not a cap
  pathToClaudeCodeExecutable: "/usr/local/bin/claude",  // the pinned binary the harness uses
  hooks: { PostToolUse: [{ matcher: "Workflow", hooks: [logWorkflowRun] }] },
  resume: process.env.RESUME_SESSION_ID,                // resumeFromRunId works in the same session only
  env: {
    ...process.env,                                     // env replaces process.env, so spread it
    ANTHROPIC_BASE_URL: process.env.GATEWAY_URL,        // the gateway adds the key; none in the VM
    ANTHROPIC_AUTH_TOKEN: process.env.SPIKE_RUN_TOKEN,  // a G0-13 run token for ticket SPIKE-1: the ticket rides in it
    ANTHROPIC_CUSTOM_HEADERS: "x-ai-agents-step: spike",  // G1-14's step header
    CLAUDE_CODE_WORKFLOW_MAX_CONCURRENT_AGENTS: "3",    // lite VM, 4 vCPU
  },
  // no maxTurns, no maxBudgetUsd, no taskBudget: limits never cut a run in the middle
};

const prompt = process.argv[2] ??
  "Run a small workflow: 3 parallel Haiku readers each list 5 files in frontend/src/components. Merge the lists.";

for await (const msg of query({ prompt, options })) {
  if (msg.type === "result") console.log(msg.subtype, msg.total_cost_usd, JSON.stringify(msg.modelUsage, null, 2));
}

export const meta = {
  name: 'nova-research',
  description: 'Parallel research before planning; for fuzzy tickets, 3 plans and a judge',
  phases: [{ title: 'Research' }, { title: 'Plans' }, { title: 'Judge' }],
}

const POINTERS = { type: 'object', required: ['pointers'], properties: { pointers: { type: 'array', items: {
  type: 'object', required: ['where', 'why'], properties: { where: { type: 'string' }, why: { type: 'string' } } } } } }
const QUESTIONS = [
  'Where is the code this ticket is about? Return file:line pointers, most relevant first.',
  'Find up to 5 merged fcp PRs that changed the same area (gh, read-only). Return the PR number and what it teaches.',
  'Which existing tests cover this area, and how are they run? Return file:line pointers.',
  'Search the brain with the kb skill for pages about this area; return path@sha and the key fact. If there is no kb skill, say "skipped".',
]

export const meta = {
  name: 'nova-review-panel',
  description: 'Review a bigger diff through several lenses, then try to refute each important finding',
  phases: [{ title: 'Lenses' }, { title: 'Skeptics' }],
}

const FINDINGS = { type: 'object', required: ['findings'], properties: { findings: { type: 'array', items: {
  type: 'object', required: ['path', 'line', 'severity', 'rule', 'body'],
  properties: { path: { type: 'string' }, line: { type: 'integer' }, severity: { enum: ['important', 'nit'] },
    rule: { type: 'string' }, body: { type: 'string' } } } } } }
const VERDICT = { type: 'object', required: ['refuted', 'evidence'],
  properties: { refuted: { type: 'boolean' }, evidence: { type: 'string' } } }

const LENSES = [
  { name: 'correctness', opts: {} },
  { name: 'security', opts: {} },
  { name: 'conventions (frontend/AGENTS.md and the Byte playbook)', opts: { model: 'sonnet', effort: 'low' } },
  { name: 'plan coverage: is every plan item and QA check done?', opts: {} },
  { name: 'tests: do they read what the user sees, and could they fail?', opts: {} },
]

const reviewed = await pipeline(LENSES,
  (lens) => agent(`Review the diff in /run/nova/review/diff.patch through the ${lens.name} lens.\nTicket:\n${args.ticket}`,
    { schema: FINDINGS, phase: 'Lenses', ...lens.opts }),
  (found) => parallel((found?.findings ?? []).filter((f) => f.severity === 'important').map((f) => () =>
    agent(`Try to refute this finding. Read the code at ${f.path}:${f.line}. If you cannot show the problem, refuted=true.\n${f.body}`,
      { schema: VERDICT, phase: 'Skeptics' }).then((v) => (v && !v.refuted ? { ...f, evidence: v.evidence } : null)))))

const kept = reviewed.flat().filter(Boolean)
log(`${kept.length} important findings survived the skeptics`)
return { findings: kept }

import { executeChild, proxyActivities } from "@temporalio/workflow";
import type * as activities from "../activities/index.js";
import type { AttemptResult, Plan } from "@rhinohealth/ai-agents-shared";
import { buildAttempt } from "./build-attempt.js";
import { act } from "../policies.js";  // G3-29 LONG preset: 7-day safety net, 2-minute heartbeats, no work limit

const { keepOnlyBranch } = proxyActivities<typeof activities>({ startToCloseTimeout: "5 minutes" });

async function attempts(key: string, plan: Plan, n = 2): Promise<AttemptResult | undefined> {
  const branches = Array.from({ length: n }, (_, i) => `nova/${key}-a${i + 1}`);
  const results = await Promise.allSettled(branches.map((branch, i) =>
    executeChild(buildAttempt, {
      workflowId: `nova:${key}:a${i + 1}`,  // each takes a Nova slot (G3) and its own fresh full VM
      args: [{ key, plan, branch }],
    })));  // allSettled: one failed attempt doesn't fail the ticket

  const survivors = results
    .filter((r): r is PromiseFulfilledResult<AttemptResult> => r.status === "fulfilled")
    .map((r) => r.value)
    .filter((a) => a.lockedChecksPass && a.verifyPass);
  if (!survivors.length) {
    await reportNoSurvivor(key, results);  // best attempt's evidence to the requester
    return undefined;
  }
  let winner = survivors[0];
  if (survivors.length > 1) {
    const choice = await act.judgeAttempts(key, survivors.map((s) => s.summary));  // ticket + diffs + check results only
    winner = survivors[choice.index];
  }
  await keepOnlyBranch(key, winner.branch, branches.filter((b) => b !== winner.branch));
  return winner;
}
